#include <stdlib.h>
#include <string.h>

int main(void) {
    char text[10001];
    scanf("%10000s", text);
    int length = (int)strlen(text);
    int start = 0;
    while (start < length) {
        int end = start + 1;
        while (end < length && text[end] == text[start]) {
            ++end;
        }
        printf("%c %d\n", text[start], end - start);
        start = end;
    }
    return 0;
}

